export function packInstanceIndex(
    stateIndex: number, 
    localIndex: number = 0, 
    isMega: boolean = false, 
    isStroke: boolean = false
): number {
    const strokeBit = isStroke ? 0x40000000 : 0;
    if (isMega || localIndex > 16383) {
        return (0x80000000 | strokeBit | ((stateIndex & 0xFFF) << 18) | (localIndex & 0x3FFFF)) >>> 0;
    }
    return (strokeBit | ((stateIndex & 0xFFFF) << 14) | (localIndex & 0x3FFF)) >>> 0;
}

fn getStateIndex(instance_index: u32) -> u32 {
    let is_mega = (instance_index & 0x80000000u) != 0u;
    return select((instance_index >> 14u) & 0xFFFFu, (instance_index >> 18u) & 0xFFFu, is_mega);
}

fn getLocalIndex(instance_index: u32) -> u32 {
    let is_mega = (instance_index & 0x80000000u) != 0u;
    return select(instance_index & 0x3FFFu, instance_index & 0x3FFFFu, is_mega);
}

fn getIsStroke(instance_index: u32) -> bool {
    return (instance_index & 0x40000000u) != 0u;
}

